<?php
namespace App\Notifications;
use App\Models\Shipment; use Illuminate\Bus\Queueable; use Illuminate\Notifications\Messages\MailMessage; use Illuminate\Notifications\Notification;
class ShipmentStatusUpdated extends Notification {use Queueable; public function __construct(public Shipment $shipment){} public function via(object $notifiable):array{return ['mail'];} public function toMail(object $notifiable):MailMessage{$status=$this->shipment->status; $message=match($status->value){'package_received'=>'Your package has been received and is now in our system.','processing'=>'Your package is currently being processed.','in_transit'=>'Your package is currently in transit.','arrived_at_destination'=>'Your package has arrived at its destination facility.','out_for_delivery'=>'Your package is now out for delivery.','delivered'=>'Your package has been marked as delivered.','delayed'=>'Your package has experienced a delay.','held'=>'Your package is currently being held.','attempt_failed'=>'A delivery attempt was unsuccessful.','returned'=>'Your package has been marked as returned.','cancelled'=>'Your shipment has been cancelled.',default=>'There has been an update to your shipment.'}; return (new MailMessage)->subject("Shipment Update — {$this->shipment->tracking_number}")->greeting("Hello {$notifiable->name},")->line($message)->line('Status: '.$status->label())->line('Current location: '.($this->shipment->current_location?:'Not available'))->action('View Shipment',route('tracking.index',['tracking'=>$this->shipment->tracking_number]));}}
